const ACTIONS: Record<FighterAction, true> = {
  idle: true,
  walk: true,
  crouch: true,
  jump: true,
  dash: true,
  backdash: true,
  attack: true,
  hitstun: true,
  blockstun: true,
  stagger: true,
  thrown: true,
  "throw-break": true,
  knockdown: true,
