import type { AddressInfo } from "node:net";
import { createEndpoint, createRouter, defineRoom, defineServer, matchMaker, WebSocketTransport, type Server } from "colyseus";
import { MATCH_ROOM, TEST_PLACEMENT_PATH, testPlacementSchema } from "@pirate-sea-race/protocol";
import { MatchRoom } from "./MatchRoom.js";

export const DEFAULT_PORT = 2593;

/** The largest WebSocket frame the transport accepts; a larger one closes that connection. */
export const MAX_FRAME_BYTES = 4096;

export interface GameServerOptions {
  /** 0 picks a free port. */
  readonly port: number;
  readonly host?: string;
  /** Install SIGINT/SIGTERM handlers that drain rooms and exit. Off for in-process tests. */
  readonly handleSignals?: boolean;
  /**
   * Test-only: serve TEST_PLACEMENT_PATH, which puts a player's ship on a chosen tile. Off by default; only the dev
   * and test entry point (`dev.ts`) and in-process tests turn it on.
   */
  readonly testPlacement?: boolean;
}

export interface RunningGameServer {
  readonly port: number;
  readonly server: Server;
  close(): Promise<void>;
}

/**
 * POST TEST_PLACEMENT_PATH with a TestPlacement body: 200 with the ship's new position, 400 for a malformed body or
 * a tile a ship cannot sit on, 404 when no match or player matches.
 */
const placeShipEndpoint = createEndpoint(TEST_PLACEMENT_PATH, { method: "POST" }, async (context) => {
  const parsed = testPlacementSchema.safeParse(context.body);
  if (!parsed.success) return Response.json({ error: "malformed placement" }, { status: 400 });
  const { code, sessionId, tileX, tileY, heading } = parsed.data;
  const [listing] = await matchMaker.query({ name: MATCH_ROOM, code });
  const room = listing === undefined ? undefined : (matchMaker.getLocalRoomById(listing.roomId) as MatchRoom | undefined);
  if (room === undefined || room.clients.get(sessionId) === undefined) return Response.json({ error: "no such player" }, { status: 404 });
  try {
    room.placeShip(sessionId, { tileX, tileY, heading });
  } catch (error) {
    return Response.json({ error: (error as Error).message }, { status: 400 });
  }
  const ship = room.state.ships.get(sessionId)!;
  return Response.json({ x: ship.x, y: ship.y, heading: ship.heading });
});

export async function startGameServer(options: GameServerOptions): Promise<RunningGameServer> {
  const server = defineServer({
    greet: false,
    gracefullyShutdown: options.handleSignals ?? true,
    transport: new WebSocketTransport({ maxPayload: MAX_FRAME_BYTES }),
    rooms: {
      // Private matches are found by their code. A create's one-time token is a filter field too, and no listing
      // holds it, so a request carrying one matches no existing match: `join` fails and `joinOrCreate` creates.
      [MATCH_ROOM]: defineRoom(MatchRoom).filterBy(["code", "createToken"]),
    },
    ...(options.testPlacement === true ? { routes: createRouter({ placeShipEndpoint }) } : {}),
  });
  await server.listen(options.port, options.host);
  const address = server.transport.server?.address() as AddressInfo | null | undefined;
  return {
    port: address?.port ?? options.port,
    server,
    close: () => server.gracefullyShutdown(false),
  };
}
import {
  INPUT_HOLD_FRAMES,
  MAX_INPUT_MESSAGES_PER_SECOND,
  validateInputMessage,
  type InputRejection,
} from "@pirate-sea-race/protocol";
import { NEUTRAL_INPUT, quantizeAxis, STEPS_PER_SECOND, type PlayerInput } from "@pirate-sea-race/simulation";

export type DropReason = InputRejection | "rate-limited";

/**
 * One client's input channel on the server: it admits messages under the rate cap, validates them against the
 * protocol and the client's last sequence, and holds the latest accepted intent for the simulation. A held input
 * lapses to neutral when no fresh one arrives within INPUT_HOLD_FRAMES (§15). World logic reads input only every
 * third frame, so a button pressed at any point since the last world step is latched until the next one (see
 * `worldStepTaken`): a quick tap released between two world steps still counts.
 */
export class InputGate {
  private lastAcceptedSeq = 0;
  private held: PlayerInput = NEUTRAL_INPUT;
  private heldAtFrame = 0;
  /** Buttons seen in any accepted message since the last world step. */
  private latchedButtons = 0;
  private windowStart = 0;
  private windowCount = 0;
  readonly dropped: Record<DropReason, number> = {
    "rate-limited": 0,
    oversized: 0,
    malformed: 0,
    "stale-sequence": 0,
    "future-frame": 0,
  };

  /** Takes one untrusted message at the server's current frame. Returns why it was dropped, or undefined. */
  receive(message: unknown, serverFrame: number): DropReason | undefined {
    if (serverFrame - this.windowStart >= STEPS_PER_SECOND) {
      this.windowStart = serverFrame;
      this.windowCount = 0;
    }
    if (++this.windowCount > MAX_INPUT_MESSAGES_PER_SECOND) return this.drop("rate-limited");
    const result = validateInputMessage(message, { lastAcceptedSeq: this.lastAcceptedSeq, serverFrame });
    if (!result.ok) return this.drop(result.reason);
    this.lastAcceptedSeq = result.input.seq;
    this.held = {
      buttons: result.input.buttons,
      moveX: quantizeAxis(result.input.moveX),
      moveY: quantizeAxis(result.input.moveY),
    };
    this.heldAtFrame = serverFrame;
    this.latchedButtons |= result.input.buttons;
    return undefined;
  }

  /** The intent the simulation uses for `frame`: the held input, plus any button latched since the last world step. */
  inputAt(frame: number): PlayerInput {
    const held = frame - this.heldAtFrame > INPUT_HOLD_FRAMES ? NEUTRAL_INPUT : this.held;
    const buttons = held.buttons | this.latchedButtons;
    return buttons === held.buttons ? held : { ...held, buttons };
  }

  /** Called after each world step has read `inputAt`: latched buttons have been seen and are released. */
  worldStepTaken(): void {
    this.latchedButtons = 0;
  }

  private drop(reason: DropReason): DropReason {
    this.dropped[reason]++;
    return reason;
  }
}
import { randomInt } from "node:crypto";
import { MATCH_CODE_ALPHABET, MATCH_CODE_LENGTH } from "@pirate-sea-race/protocol";

/** A random private match code such as `K7Q2MX`. Uniqueness is checked by the room against live listings. */
export function generateMatchCode(pick: (bound: number) => number = randomInt): string {
  let code = "";
  for (let index = 0; index < MATCH_CODE_LENGTH; index++) code += MATCH_CODE_ALPHABET[pick(MATCH_CODE_ALPHABET.length)];
  return code;
}

