import { readFile } from "node:fs/promises";
import {
  createDuelInputLog,
  createDuelState,
  defaultDuelConfig,
  replayDuel,
  type DuelConfig,
  type DuelInputLog,
  type DuelInputs,
  type DuelReplay,
