import type { IslandTheme } from "@pirate-sea-race/content";

/**
 * The scene's placeholder palette, kept free of Phaser so the browser tests can check the canvas against it. None of
 * these is near a ship colour, so a ship's colour on the canvas is always a ship.
 */
export const SEA_COLOR = 0x0b3d5c;
export const GRID_COLOR = 0x145374;
export const SHOAL_COLOR = 0x2e7d86;
export const SHOAL_FLECK = 0x4f9aa0;
export const DOCK_COLOR = 0x8b5a2b;
export const DOCK_PLANK = 0x6b4220;
export const LAND_COLORS: Readonly<Record<IslandTheme, number>> = { tropical: 0x6b8e23, volcanic: 0x5b4a45, ruin: 0x9a8f73, mist: 0x7d8a99 };
export const FOG_COLOR = 0x16202a;
export const OWN_RING_COLOR = 0xfff3b0;
export const SIGHT_COLOR = 0x9bd1e5;
import { defaultSimulationConfig } from "@pirate-sea-race/simulation";

const { map } = defaultSimulationConfig;
export const TILE_PIXELS = 16;
/** The canvas; the map is larger, so the camera follows the player's ship. */
export const VIEW_WIDTH = 800;
export const VIEW_HEIGHT = 560;

/** The camera's top-left corner, in whole pixels, that centres a point, kept inside the map. */
export function followScroll(centreX: number, centreY: number): { x: number; y: number } {
  const clamp = (value: number, max: number) => Math.max(0, Math.min(max, Math.round(value)));
  return {
    x: clamp(centreX - VIEW_WIDTH / 2, map.widthTiles * TILE_PIXELS - VIEW_WIDTH),
    y: clamp(centreY - VIEW_HEIGHT / 2, map.heightTiles * TILE_PIXELS - VIEW_HEIGHT),
  };
}
import { INTERPOLATION_DELAY_MS, SnapshotBuffer } from "./interpolation.js";

/** A ship as the server last sent it: only the client's own ship and ships in its sight ever arrive (§16). */
export interface ShipSnapshot {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly heading: number;
  readonly speed: number;
  /** The dock it is moored at, or -1 at sea. */
  readonly dock: number;
}

/** Placeholder ship colours by spawn slot. */
const SLOT_COLORS = [0xf4b942, 0xe5484d, 0x46a758, 0xb66ee8, 0xf76b15, 0x3dd6d0, 0xf2f2f2, 0xd6409f] as const;

export function slotColor(slot: number): number {
  return SLOT_COLORS[slot % SLOT_COLORS.length]!;
}

export function cssColor(color: number): string {
  return `#${color.toString(16).padStart(6, "0")}`;
}

/**
 * The client's picture of the match: the latest decoded server state of each visible ship (for the HUD) and a
 * snapshot history per ship (for interpolated drawing). A ship that leaves the decoded state is forgotten at once.
 */
export class MatchView {
  private readonly latest = new Map<string, ShipSnapshot>();
  private readonly buffers = new Map<string, SnapshotBuffer>();

  constructor(readonly selfId: string) {}

  ingest(ships: Iterable<ShipSnapshot>, now: number): void {
    const seen = new Set<string>();
    for (const ship of ships) {
      seen.add(ship.id);
      const { id, slot, x, y, heading, speed, dock } = ship;
      this.latest.set(id, { id, slot, x, y, heading, speed, dock });
      let buffer = this.buffers.get(id);
      if (buffer === undefined) this.buffers.set(id, (buffer = new SnapshotBuffer()));
      buffer.push(now, x, y);
    }
    for (const id of [...this.latest.keys()]) {
      if (seen.has(id)) continue;
      this.latest.delete(id);
      this.buffers.delete(id);
    }
  }

  ships(): ShipSnapshot[] {
    return [...this.latest.values()];
  }

  ship(id: string): ShipSnapshot | undefined {
    return this.latest.get(id);
  }

  /** Where to draw a ship at `now`, interpolated INTERPOLATION_DELAY_MS in the past. */
  renderPosition(id: string, now: number): { x: number; y: number } | undefined {
    return this.buffers.get(id)?.sample(now - INTERPOLATION_DELAY_MS);
  }
}
  display: grid;
  grid-template-columns: auto auto;
  gap: 0.25rem 1rem;
  margin: 0;
}

#hud dt {
  color: #9bb8c6;
}

#hud dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

#hud ul {
  list-style: none;
  padding: 0;
  font-variant-numeric: tabular-nums;
}

.swatch {
  display: inline-block;
  width: 0.75em;
  height: 0.75em;
  border-radius: 50%;
  margin-right: 0.4em;
}
describe("MatchView", () => {
  const ship = (x: number, y: number) => ({ id: "a", slot: 0, x, y, heading: 0, speed: 0, dock: -1 });

  it("draws ships between two snapshots INTERPOLATION_DELAY_MS behind now, not at the latest one", () => {
    const view = new MatchView("a");
    view.ingest([ship(0, 500)], 1000);
    view.ingest([ship(100, 500)], 1050);
    view.ingest([ship(200, 600)], 1100);
    expect(INTERPOLATION_DELAY_MS).toBe(100);
    // At 1175 the scene draws the ship as it was at 1075, halfway between the patches of 1050 and 1100.
    const drawn = view.renderPosition("a", 1175)!;
    expect(drawn).toEqual({ x: 150, y: 550 });
    expect(drawn.x).toBeGreaterThan(100);
    expect(drawn.x).toBeLessThan(200);
    // The HUD's readout is the latest decoded server position.
    expect(view.ships()).toEqual([ship(200, 600)]);
    // Once now is INTERPOLATION_DELAY_MS past the last patch, the drawing catches up with it.
    expect(view.renderPosition("a", 1100 + INTERPOLATION_DELAY_MS)).toEqual({ x: 200, y: 600 });
  });

  it("forgets a ship that leaves the decoded state, as one that sails out of sight does", () => {
    const view = new MatchView("a");
    view.ingest([ship(0, 0)], 0);
    view.ingest([], 50);
    expect(view.renderPosition("a", 200)).toBeUndefined();
    expect(view.ships()).toEqual([]);
  });
});

describe("keyboard axes", () => {
  it("makes opposing keys neutral", () => {
    expect(axis(true, true)).toBe(0);
    expect(axis(true, false)).toBe(-1);
    expect(axis(false, true)).toBe(1);
    expect(axis(false, false)).toBe(0);
  });
});

describe("frame estimate", () => {
  it("advances the last patched frame by elapsed match time, within the lead limit", () => {
    expect(estimateServerFrame(300, 1000, 1000)).toBe(300);
    expect(estimateServerFrame(300, 1000, 1050)).toBe(303);
    expect(estimateServerFrame(300, 1000, 60_000)).toBe(315);
  });
});

describe("input sender", () => {
  function recorder() {
    const sent: InputMessage[] = [];
    return { sent, sender: new InputSender({ send: (type, message) => type === MessageType.Input && sent.push(message) }) };
  }

  it("sends the interact button and resends held input, but stays quiet at rest", () => {
    const { sent, sender } = recorder();
    sender.update({ moveX: 0, moveY: 0, buttons: 0 }, 0);
    expect(sent).toHaveLength(0);
    sender.update({ moveX: 0, moveY: -1, buttons: 0 }, 10);
    sender.update({ moveX: 0, moveY: -1, buttons: 0 }, 50);
    sender.update({ moveX: 0, moveY: -1, buttons: 0 }, 120);
    sender.update({ moveX: 0, moveY: 0, buttons: Buttons.Interact }, 130);
    sender.update({ moveX: 0, moveY: 0, buttons: Buttons.Interact }, 240);

