  switch (fighter.action) {
    case "hitstun":
    case "knockdown":
      return 0xff5a4f;
    case "blockstun":
      return 0xffffff;
    case "stagger":
      return 0xff9f1c;
    case "thrown":
    case "throw-break":
      return 0xc77dff;
    case "attack":
      return activeHitbox(fighter) === undefined ? 0xfff3b0 : 0xff3b30;
    default:
      return 0x0b1620;
  }
}

