async function measure(page: any) {
  await page.evaluate(() => {
    (window as any).__keys = [];
    window.addEventListener("keydown", (e) => (window as any).__keys.push([e.code, performance.now()]));
  });
  const gaps: number[] = [];
  for (let i = 0; i < 12; i++) {
    await page.evaluate(() => ((window as any).__keys = []));
    await page.keyboard.down("j");
    await page.keyboard.down("k");
    await page.waitForTimeout(50);
    await page.keyboard.up("j");
    await page.keyboard.up("k");
    const keys = await page.evaluate(() => (window as any).__keys);
    gaps.push(Math.round((keys[1][1] - keys[0][1]) * 10) / 10);
    await page.waitForTimeout(200);
  }
  return gaps;
}
test("gap", async ({ page }) => {
  await page.goto("/");
  console.log("landing gaps ms", JSON.stringify(await measure(page)));
  await page.getByRole("button", { name: "Practice" }).click();
  await page.waitForTimeout(4000);
  const busy = await page.evaluate(async () => {
    const samples: number[] = [];
    let last = performance.now();
    await new Promise<void>((resolve) => {
      const t = setInterval(() => { const now = performance.now(); samples.push(now - last); last = now; if (samples.length > 300) { clearInterval(t); resolve(); } }, 4);
    });
    samples.sort((a, b) => a - b);
    return { p50: samples[150], p90: samples[270], max: samples[299] };
  });
  console.log("interval", JSON.stringify(busy));
  const raf = await page.evaluate(async () => {
    const samples: number[] = [];
    let last = performance.now();
    await new Promise<void>((resolve) => {
      const f = () => { const now = performance.now(); samples.push(now - last); last = now; if (samples.length > 60) resolve(); else requestAnimationFrame(f); };
      requestAnimationFrame(f);
    });
    samples.sort((a, b) => a - b);
    return { p50: samples[30], p90: samples[54], max: samples[60] };
  });
  console.log("raf", JSON.stringify(raf));
  console.log("duel gaps ms", JSON.stringify(await measure(page)));
});
EOF
